/* Faturalar, irsaliyeler, iadeler, teklifler, siparişler — belge düzenleyici, yazdırma, UBL-TR XML, dönüştürme, kargo, B2B katalog */
(function () {
  const { $, $$, esc, money, icon } = CS;
  const T = CS.DOC_TYPES;
  CS.ORDER_STATUS = { yeni: 'Yeni', hazirlaniyor: 'Hazırlanıyor', kargoda: 'Kargoda', teslim: 'Teslim edildi', faturalandi: 'Faturalandı', iptal: 'İptal' };
  CS.QUOTE_STATUS = { bekliyor: 'Yanıt bekliyor', onaylandi: 'Onaylandı', reddedildi: 'Reddedildi', suresi: 'Süresi doldu', siparis: 'Siparişe dönüştü', faturalandi: 'Faturalandı' };
  CS.EDOC_STATUS = { taslak: 'Taslak', hazir: 'Gönderime hazır (XML)', gonderildi: 'Entegratöre gönderildi', onay: 'Onaylandı', red: 'Reddedildi', iptal: 'İptal' };
  CS.CHANNELS = { magaza: 'Mağaza', telefon: 'Telefon', whatsapp: 'WhatsApp', eposta: 'E-posta', web: 'Web sitesi', b2b: 'B2B katalog', saha: 'Saha satış', trendyol: 'Trendyol', hepsiburada: 'Hepsiburada', n11: 'n11', amazon: 'Amazon', ciceksepeti: 'Çiçeksepeti', pazarama: 'Pazarama', idefix: 'İdefix' };
  CS.CARGO = ['Yurtiçi Kargo', 'Aras Kargo', 'MNG Kargo', 'PTT Kargo', 'Sürat Kargo', 'UPS', 'DHL', 'Kolay Gelsin', 'HepsiJet', 'Trendyol Express', 'Kendi aracımız'];

  const payState = (d) => { if (!T[d.type].cari || !d.cid && !['pos', 'pos_iade'].includes(d.type)) return null; const paid = CS.docPaid(d); const rest = CS.round(d.totalTry - paid); if (rest <= 0.009) return ['ok', 'Ödendi']; if (paid > 0) return ['warn', 'Kısmi']; if (d.due && d.due < CS.today()) return ['bad', 'Vadesi geçti']; return ['', d.cid ? 'Açık' : '—']; };

  /* ================= FATURALAR ================= */
  const DTABS = [['sales', 'Satış faturaları', 'docs', ['satis']], ['buys', 'Alış faturaları', 'docs/buys', ['alis']], ['returns', 'İadeler', 'docs/returns', ['satis_iade', 'alis_iade', 'pos_iade']], ['desp', 'İrsaliyeler', 'docs/desp', ['irsaliye', 'alis_irsaliye']], ['receipts', 'Perakende fişleri', 'docs/receipts', ['pos']], ['edoc', 'e-Belge kutusu', 'docs/edoc', null]];
  CS.mod('docs', {
    title: 'Faturalar ve belgeler',
    render(page, prm) {
      const sub = prm._[0] || 'sales';
      if (sub === 'new') return editor(page, { type: prm._[1] || 'satis', cid: prm.cid || '' });
      if (sub === 'edit') return editor(page, CS.byId('docs', prm._[1]));
      if (sub === 'view') return view(page, CS.byId('docs', prm._[1]));
      const tab = DTABS.find((t) => t[0] === sub && (CS.canCost() || t[0] !== 'buys')) || DTABS[0];
      const can = CS.can('docs', 'e');
      const body = CS.head(page, 'Faturalar ve belgeler', can ? CS.btn('Satış faturası', 'ns', 'primary', 'plus') + (CS.canCost() ? CS.btn('Alış faturası', 'nb', '', 'plus') : '') + CS.btn('İade', 'nr', '', 'ret') + CS.btn('İrsaliye', 'nd', '', 'truck') : '', DTABS.filter((t) => CS.canCost() || t[0] !== 'buys').map((t) => t.slice(0, 3)), tab[0]);
      CS.bind(page, { ns: () => CS.go('docs/new/satis'), nb: () => CS.go('docs/new/alis'), nr: () => CS.modal({ title: 'İade türü', size: 'sm', body: '<p>Hangi iadeyi oluşturmak istiyorsunuz?</p>', buttons: [{ label: 'Alıştan iade (tedarikçiye)', onClick: () => CS.go('docs/new/alis_iade') }, { label: 'Satıştan iade (müşteriden)', kind: 'primary', onClick: () => CS.go('docs/new/satis_iade') }] }), nd: () => CS.go('docs/new/irsaliye') });
      if (tab[0] === 'edoc') return edocBox(body);
      docList(body, tab[3], 'docs');
    }
  });

  function docList(body, types, mod) {
    const st = { pay: '', edoc: '', status: '' };
    body.innerHTML = '<div id="rng" style="margin-bottom:10px"></div><div id="dt"></div>';
    const isOrder = mod === 'orders';
    const rows = (a, b) => CS.db.docs.filter((d) => types.includes(d.type) && d.date >= a && d.date <= b && (!CS.branchId || !d.branchId || d.branchId === CS.branchId) && (!st.edoc || d.edoc === st.edoc) && (!st.status || d.status === st.status) && (!st.pay || (payState(d) || [])[1] === st.pay)).sort((x, y) => (y.date + y.createdAt).localeCompare(x.date + x.createdAt));
    let tbl; const r = CS.dateRange($('#rng', body), (a, b) => tbl.redraw(rows(a, b)), isOrder ? 'all' : 'month');
    const statusMap = types.includes('teklif') ? CS.QUOTE_STATUS : isOrder ? CS.ORDER_STATUS : null;
    tbl = CS.table($('#dt', body), {
      rows: rows(...r.get()), ph: 'Belge no, cari…', searchText: (d) => [d.no, d.eno, CS.contactName(d.cid), d.buyer, d.mpNo, d.desc, d.cargoNo].join(' '),
      tools: `${statusMap ? `<select id="fs" aria-label="Durum"><option value="">Tüm durumlar</option>${Object.entries(statusMap).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select>` : `<select id="fp" aria-label="Ödeme durumu"><option value="">Tüm ödeme durumları</option><option>Ödendi</option><option>Kısmi</option><option>Açık</option><option>Vadesi geçti</option></select><select id="fe" aria-label="Belge tipi"><option value="">Tüm belge tipleri</option>${Object.entries(CS.EDOC).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select>`}<button class="btn" id="dx">${icon('down', 15)} Excel</button>`,
      cols: [{ l: 'Tarih', k: 'date', f: (d) => CS.date(d.date) }, { l: 'Belge', v: (d) => d.no, f: (d) => `<b>${esc(d.no)}</b><small>${esc(T[d.type].short)}${d.edoc ? ' · ' + esc(CS.EDOC[d.edoc] || '') : ''}${d.channel ? ' · ' + esc(CS.CHANNELS[d.channel] || d.channel) : ''}</small>` }, { l: 'Cari', v: (d) => CS.contactName(d.cid) || d.buyer || '', f: (d) => esc(CS.contactName(d.cid) || d.buyer || 'Perakende') + (d.mpNo ? `<small>${esc(d.mpNo)}</small>` : '') }, ...(isOrder ? [{ l: 'Termin / geçerlilik', v: (d) => d.valid || d.deliver || '', f: (d) => CS.date(d.valid || d.deliver) }] : [{ l: 'Vade', k: 'due', f: (d) => CS.date(d.due) }]), { l: 'Tutar', a: 'r', v: (d) => d.totalTry, f: (d) => `<b>${money(d.total, d.currency)}</b>${d.currency && d.currency !== '₺' ? `<small>${money(d.totalTry)}</small>` : ''}` }, { l: 'Durum', v: (d) => (statusMap ? statusMap[d.status] : (payState(d) || [])[1]) || '', f: (d) => { if (d.status === 'iptal') return '<span class="pill bad">İptal</span>'; if (statusMap) return `<span class="pill ${d.status === 'teslim' || d.status === 'onaylandi' || d.status === 'faturalandi' ? 'ok' : d.status === 'reddedildi' ? 'bad' : 'info'}">${esc(statusMap[d.status] || d.status)}</span>`; const p = payState(d); return p ? `<span class="pill ${p[0]}">${p[1]}</span>` : ''; } }],
      onRow: (d) => CS.go((isOrder ? 'orders' : 'docs') + '/view/' + d.id),
      actions: (d) => CS.actBtn('print', 'Yazdır', 'print') + (CS.can(mod, 'e') && d.status !== 'iptal' ? CS.actBtn('edit', 'Düzenle', 'edit') : ''),
      onAct: (a, d) => (a === 'print' ? printDoc(d) : CS.go(mod + '/edit/' + d.id)),
      foot: (rs) => `<tr><td colspan="4">${rs.length} belge</td><td class="r">${money(CS.sum(rs.filter((d) => d.status !== 'iptal'), 'totalTry'))}</td><td></td><td></td></tr>`
    });
    const fp = $('#fp', body), fe = $('#fe', body), fs = $('#fs', body);
    fp && (fp.onchange = () => { st.pay = fp.value; tbl.redraw(rows(...r.get())); }); fe && (fe.onchange = () => { st.edoc = fe.value; tbl.redraw(rows(...r.get())); }); fs && (fs.onchange = () => { st.status = fs.value; tbl.redraw(rows(...r.get())); });
    $('#dx', body).onclick = () => CS.exportXLS('belgeler', ['Tarih', 'Belge no', 'Tür', 'Cari', 'VKN/TCKN', 'Vade', 'KDV hariç', 'KDV', 'Toplam', 'Döviz', 'Durum'], tbl.rows().map((d) => [CS.date(d.date), d.no, T[d.type].label, CS.contactName(d.cid), CS.contact(d.cid)?.taxNo || CS.contact(d.cid)?.tc || '', CS.date(d.due), CS.round(d.net || 0), CS.round(d.kdvTotal || 0), d.total, d.currency || '₺', d.status]));
  }

  /* ---------- e-Belge kutusu ---------- */
  function edocBox(body) {
    const out = CS.db.docs.filter((d) => ['efatura', 'earsiv', 'eirsaliye', 'eihracat', 'esmm'].includes(d.edoc) && T[d.type].side === 'sale' && d.type !== 'pos');
    const inc = CS.db.docs.filter((d) => d.edoc && T[d.type].side === 'buy' && ['efatura', 'eirsaliye'].includes(d.edoc));
    body.innerHTML = `<p class="alert info">Belgeleriniz UBL-TR 1.2 formatında XML olarak hazırlanır. Gerçek gönderim (GİB onayı) için Entegrasyonlar bölümünde bir özel entegratör (ör. MySoft, eLogo, EDM, e-Dönüştür) tanımlayın ya da XML’leri entegratör portalına yükleyin. Gelen e-faturaları XML olarak içe aktarabilirsiniz.</p>
      <div class="kpis">${CS.kpi('Giden e-belge', out.length, out.filter((d) => (d.estatus || 'taslak') === 'taslak').length + ' taslak')}${CS.kpi('Gelen e-belge', inc.length)}${CS.kpi('Bu ay e-Fatura', out.filter((d) => d.edoc === 'efatura' && d.date.slice(0, 7) === CS.today().slice(0, 7)).length)}${CS.kpi('Bu ay e-Arşiv', out.filter((d) => d.edoc === 'earsiv' && d.date.slice(0, 7) === CS.today().slice(0, 7)).length)}</div>
      <div class="row" style="margin-bottom:10px">${CS.btn('Gelen e-fatura XML içe aktar', 'imp', '', 'upload')}${CS.btn('Seçilenleri XML olarak indir', 'zip', '', 'down')}${CS.btn('Seçilenleri gönderildi işaretle', 'mark', '', 'check')}</div><h2 style="font-size:16px">Giden</h2><div id="eo"></div><h2 style="font-size:16px;margin-top:16px">Gelen</h2><div id="ei"></div>`;
    const cols = [{ l: '', f: (d) => `<input type="checkbox" data-sel="${d.id}" aria-label="Seç">` }, { l: 'Tarih', k: 'date', f: (d) => CS.date(d.date) }, { l: 'Belge', v: (d) => d.no, f: (d) => `<b>${esc(d.no)}</b><small>${esc(CS.EDOC[d.edoc])} · ${esc(d.scenario || '')}</small>` }, { l: 'ETTN', v: (d) => d.uuid || '', f: (d) => `<small>${esc(d.uuid || '—')}</small>` }, { l: 'Cari', v: (d) => CS.contactName(d.cid) }, { l: 'Tutar', a: 'r', v: (d) => d.totalTry, f: (d) => money(d.total, d.currency) }, { l: 'Durum', v: (d) => CS.EDOC_STATUS[d.estatus || 'taslak'], f: (d) => `<span class="pill ${d.estatus === 'onay' ? 'ok' : d.estatus === 'red' ? 'bad' : d.estatus === 'gonderildi' ? 'info' : 'warn'}">${CS.EDOC_STATUS[d.estatus || 'taslak']}</span>` }];
    CS.table($('#eo', body), { rows: out.slice().reverse(), cols, onRow: (d) => CS.go('docs/view/' + d.id), actions: () => CS.actBtn('xml', 'XML indir', 'down'), onAct: (a, d) => downloadXML(d) });
    CS.table($('#ei', body), { rows: inc.slice().reverse(), cols: cols.slice(1), onRow: (d) => CS.go('docs/view/' + d.id), empty: 'Gelen e-belge yok.' });
    const sel = () => $$('[data-sel]:checked', body).map((i) => CS.byId('docs', i.dataset.sel));
    CS.bind(body, { zip: () => sel().forEach((d, i) => setTimeout(() => downloadXML(d), i * 300)), mark: () => { sel().forEach((d) => { d.estatus = 'gonderildi'; d.sentAt = CS.now(); }); CS.save(); CS.route(); }, imp: importXML });
  }
  function importXML() {
    CS.modal({ title: 'Gelen e-fatura içe aktar', body: '<p class="muted">Tedarikçinizden ya da entegratör portalından indirdiğiniz UBL-TR XML dosyalarını seçin. Tedarikçi yoksa oluşturulur, ürünler barkod/ad ile eşleştirilir; eşleşmeyenler açıklama satırı olarak eklenir.</p><input type="file" id="xf" accept=".xml" multiple>', buttons: [{ label: 'Vazgeç' }, {
      label: 'İçe aktar', kind: 'primary', onClick: async (x, el) => {
        const files = $('#xf', el).files; let n = 0;
        for (const file of files) {
          try {
            const xml = new DOMParser().parseFromString(await file.text(), 'application/xml'); const q = (n2, ctx = xml) => ctx.getElementsByTagNameNS('*', n2)[0]; const qa = (n2, ctx = xml) => Array.from(ctx.getElementsByTagNameNS('*', n2)); const txt = (n2, ctx) => q(n2, ctx)?.textContent?.trim() || '';
            const sup = q('AccountingSupplierParty'); const vkn = qa('ID', sup).map((i) => i.textContent.trim()).find((s) => /^\d{10,11}$/.test(s)); const name = txt('RegistrationName', sup) || txt('Name', sup) || 'Tedarikçi';
            let c = CS.db.contacts.find((k) => vkn && (k.taxNo === vkn || k.tc === vkn)); if (!c) { c = { id: 'c_' + CS.uid(), name, title: name, kind: 'tedarikci', taxNo: vkn, taxOffice: txt('Name', q('PartyTaxScheme', sup)), city: txt('CityName', sup), address: txt('StreetName', sup), efatura: true, createdAt: CS.today(), priceList: 0 }; CS.db.contacts.push(c); }
            const lines = qa('InvoiceLine').map((L) => { const nm = txt('Name', q('Item', L)); const bc = txt('ID', q('SellersItemIdentification', L)) || txt('ID', q('StandardItemIdentification', L)); const p = CS.findByBarcode(bc) || CS.db.products.find((pp) => CS.trLower(pp.name) === CS.trLower(nm)); return { pid: p?.id || '', name: nm, qty: CS.num(txt('InvoicedQuantity', L)), unit: p?.unit || 'Adet', price: CS.num(txt('PriceAmount', L)), kdv: CS.num(txt('Percent', L)), disc: 0 }; });
            const d = { type: CS.match(txt('InvoiceTypeCode'), 'IADE') ? 'alis_iade' : 'alis', date: txt('IssueDate'), cid: c.id, wh: CS.defaultWh(), lines, currency: '₺', rate: 1, edoc: 'efatura', estatus: 'onay', eno: txt('ID'), uuid: txt('UUID'), status: 'onay', desc: 'XML içe aktarım: ' + file.name };
            if (CS.db.docs.some((x) => x.uuid && x.uuid === d.uuid)) { CS.toast(file.name + ' daha önce aktarılmış.', 'warn'); continue; }
            CS.postDoc(d); n++;
          } catch (e) { CS.toast(file.name + ' okunamadı: ' + e.message, 'bad'); }
        }
        CS.toast(n + ' e-fatura içe aktarıldı.'); CS.route();
      }
    }] });
  }

  /* ================= SİPARİŞ VE TEKLİF ================= */
  const OTABS = [['quotes', 'Teklifler', 'orders', ['teklif']], ['sales', 'Müşteri siparişleri', 'orders/sales', ['siparis']], ['buys', 'Tedarikçi siparişleri', 'orders/buys', ['alis_siparis']], ['reserve', 'Bekleyen sipariş stokları', 'orders/reserve', null], ['b2b', 'B2B katalog', 'orders/b2b', null]];
  CS.mod('orders', {
    title: 'Siparişler ve teklifler',
    render(page, prm) {
      const sub = prm._[0] || 'quotes';
      if (sub === 'new') return editor(page, { type: prm._[1] || 'teklif', cid: prm.cid || '' }, 'orders');
      if (sub === 'edit') return editor(page, CS.byId('docs', prm._[1]), 'orders');
      if (sub === 'view') return view(page, CS.byId('docs', prm._[1]), 'orders');
      const tab = OTABS.find((t) => t[0] === sub) || OTABS[0];
      const body = CS.head(page, 'Siparişler ve teklifler', CS.can('orders', 'e') ? CS.btn('Yeni teklif', 'nq', 'primary', 'plus') + CS.btn('Müşteri siparişi', 'ns', '', 'plus') + (CS.canCost() ? CS.btn('Tedarikçi siparişi', 'nb', '', 'plus') : '') : '', OTABS.filter((t) => CS.canCost() || t[0] !== 'buys').map((t) => t.slice(0, 3)), tab[0]);
      CS.bind(page, { nq: () => CS.go('orders/new/teklif'), ns: () => CS.go('orders/new/siparis'), nb: () => CS.go('orders/new/alis_siparis') });
      if (tab[0] === 'reserve') return reserve(body);
      if (tab[0] === 'b2b') return b2b(body);
      if (tab[0] === 'sales') { const ch = CS.groupBy(CS.db.docs.filter((d) => d.type === 'siparis' && !['iptal', 'faturalandi', 'teslim'].includes(d.status)), (d) => d.channel || 'magaza'); const k = document.createElement('div'); k.className = 'kpis'; k.innerHTML = Object.entries(ch).map(([c, L]) => CS.kpi(CS.CHANNELS[c] || c, L.length + ' açık sipariş', money(CS.sum(L, 'totalTry')))).join('') || ''; body.before(k); }
      docList(body, tab[3], 'orders');
    }
  });
  function reserve(body) {
    const open = CS.db.docs.filter((d) => d.type === 'siparis' && ['yeni', 'hazirlaniyor'].includes(d.status));
    const inc = CS.db.docs.filter((d) => d.type === 'alis_siparis' && ['yeni', 'hazirlaniyor', 'kargoda'].includes(d.status));
    const by = {}; open.forEach((d) => d.lines.forEach((l) => { if (!l.pid) return; (by[l.pid] = by[l.pid] || { pid: l.pid, res: 0, inc: 0 }).res += CS.num(l.qty); })); inc.forEach((d) => d.lines.forEach((l) => { if (!l.pid) return; (by[l.pid] = by[l.pid] || { pid: l.pid, res: 0, inc: 0 }).inc += CS.num(l.qty); }));
    body.innerHTML = '<p class="muted">Açık müşteri siparişlerinin ayırdığı (rezerve) stok ve yoldaki tedarikçi siparişleri.</p><div id="rt"></div>';
    CS.table($('#rt', body), { rows: Object.values(by), empty: 'Açık sipariş yok.', cols: [{ l: 'Ürün', v: (x) => CS.productName(x.pid) }, { l: 'Mevcut stok', a: 'r', v: (x) => CS.stockOf(x.pid), f: (x) => CS.qty(CS.stockOf(x.pid)) }, { l: 'Rezerve (müşteri siparişi)', a: 'r', v: (x) => x.res, f: (x) => CS.qty(x.res) }, { l: 'Yolda (tedarikçi siparişi)', a: 'r', v: (x) => x.inc, f: (x) => CS.qty(x.inc) }, { l: 'Serbest stok', a: 'r', v: (x) => CS.stockOf(x.pid) - x.res, f: (x) => { const v = CS.stockOf(x.pid) - x.res; return `<b class="${v < 0 ? 'neg' : ''}">${CS.qty(v)}</b>`; } }, { l: 'Eksik', a: 'r', v: (x) => Math.max(0, x.res - CS.stockOf(x.pid) - x.inc), f: (x) => { const v = Math.max(0, x.res - CS.stockOf(x.pid) - x.inc); return v ? `<span class="neg">${CS.qty(v)}</span>` : ''; } }], tools: `<button class="btn" id="mk">Eksikler için tedarikçi siparişi oluştur</button>` });
    $('#mk', body).onclick = () => { const lines = Object.values(by).filter((x) => x.res - CS.stockOf(x.pid) - x.inc > 0).map((x) => { const p = CS.product(x.pid); return { pid: p.id, name: CS.productName(p), qty: x.res - CS.stockOf(x.pid) - x.inc, unit: p.unit, price: CS.num(p.buy), kdv: p.kdv, disc: 0 }; }); if (!lines.length) return CS.toast('Eksik ürün yok.'); CS.docDraft = { type: 'alis_siparis', lines }; CS.go('orders/new/alis_siparis'); };
  }

  /* ---------- B2B katalog (Bizim Sipariş benzeri) ---------- */
  function b2b(body) {
    const s = CS.db.settings.b2b = CS.db.settings.b2b || { title: CS.db.company.name + ' ürün kataloğu', list: 0, showStock: true, minOrder: 0, whatsapp: CS.db.company.phone || '', note: 'Siparişiniz WhatsApp üzerinden bize iletilir. Onay sonrası hazırlanır.' };
    const ps = CS.db.products.filter((p) => p.active !== false && !p.parentId && (p.online || !CS.db.products.some((x) => x.online)));
    body.innerHTML = `<div class="grid g2"><section class="panel"><h2>Katalog ayarları</h2><div id="bf"></div><p class="muted">Katalogda ${ps.length} ürün yayınlanacak. Ürün kartında “B2B katalogda yayınla” işaretli ürün yoksa tüm aktif ürünler yayınlanır.</p><div class="row"><button class="btn primary" data-a="dl">${icon('down', 15)} Paylaşılabilir katalog dosyası oluştur</button><a class="btn" href="catalog.html" target="_blank">${icon('eye', 15)} Bu cihazda katalogu aç</a></div></section>
      <section class="panel"><h2>Nasıl çalışır?</h2><div class="timeline"><div>Katalog dosyasını oluşturun; fiyat, görsel ve stoklarınız içine gömülür.</div><div>Dosyayı müşterilerinize e-posta, WhatsApp ya da kendi web sitenizden gönderin. Açmak için internet ya da kurulum gerekmez.</div><div>Müşteri ürünleri sepete ekler, “Siparişi gönder” dediğinde sipariş WhatsApp mesajı olarak size gelir; mesajın sonunda sipariş kodu yer alır.</div><div>Mesajdaki kodu “Siparişi içe aktar” alanına yapıştırın; sipariş otomatik oluşur ve faturaya dönüştürülebilir.</div><div>Bu cihazda açtığınız katalogdan verilen siparişler doğrudan “Müşteri siparişleri” listesine düşer.</div></div>
      <h2 style="margin-top:14px">Siparişi içe aktar</h2><textarea id="code" rows="4" style="width:100%" placeholder="WhatsApp mesajındaki CEPSTOK-SIPARIS kodunu yapıştırın"></textarea><p><button class="btn" data-a="imp">Siparişi oluştur</button></p></section></div>`;
    const f = CS.form([{ k: 'title', l: 'Katalog başlığı', w: 'full' }, { k: 'list', l: 'Fiyat listesi', t: 'select', opts: CS.db.settings.priceLists.map((n, i) => [String(i), n]) }, { k: 'whatsapp', l: 'Siparişlerin geleceği WhatsApp numarası' }, { k: 'minOrder', l: 'Asgari sipariş tutarı', t: 'money' }, { k: 'showStock', l: 'Stok durumunu göster', t: 'check' }, { k: 'note', l: 'Katalog notu', t: 'textarea', w: 'full' }], { ...s, list: String(s.list) });
    $('#bf', body).appendChild(f); f.addEventListener('change', () => { Object.assign(s, f.read()); s.list = +s.list; CS.save(); });
    CS.bind(body, {
      dl: () => { Object.assign(s, f.read()); s.list = +s.list; CS.save(); CS.buildCatalogFile(); },
      imp: () => { const raw = $('#code', body).value; const m = raw.match(/CEPSTOK-SIPARIS:([A-Za-z0-9+/=]+)/); if (!m) return CS.toast('Sipariş kodu bulunamadı.', 'bad'); try { const o = JSON.parse(decodeURIComponent(escape(atob(m[1])))); CS.createCatalogOrder(o); $('#code', body).value = ''; } catch (e) { CS.toast('Kod çözülemedi.', 'bad'); } }
    });
  }
  CS.catalogData = function () {
    const s = CS.db.settings.b2b || { list: 0 }; const ps = CS.db.products.filter((p) => p.active !== false && !p.parentId && (p.online || !CS.db.products.some((x) => x.online)));
    return { company: CS.db.company.name, phone: CS.db.company.phone, title: s.title, note: s.note, whatsapp: CS.waNum ? CS.waNum(s.whatsapp) : s.whatsapp, minOrder: s.minOrder, showStock: s.showStock, cats: CS.db.categories.map((c) => ({ id: c.id, name: c.name })), products: ps.map((p) => ({ id: p.id, name: p.name, cat: p.cat, unit: p.unit, price: CS.grossPrice(p, s.list), image: p.image || '', desc: p.desc || '', barcode: p.barcode || '', stock: p.variants?.length ? CS.sum(p.variants, (v) => CS.stockOf(v)) : p.service ? 999 : CS.stockOf(p), variants: (p.variants || []).map(CS.product).filter(Boolean).map((v) => ({ id: v.id, name: Object.values(v.attrs).join(' / '), price: CS.grossPrice(v, s.list), stock: CS.stockOf(v) })) })) };
  };
  CS.buildCatalogFile = async function () {
    let tpl; try { tpl = await (await fetch('catalog.html')).text(); } catch (e) { tpl = null; }
    if (!tpl) { CS.toast('Katalog şablonu okunamadı. Uygulamayı bir web sunucusundan açtığınızdan emin olun ya da “Bu cihazda katalogu aç” seçeneğini kullanın.', 'bad', 6000); return; }
    const data = JSON.stringify(CS.catalogData()).replace(/</g, '\\u003c');
    CS.download(CS.trLower(CS.db.company.name).replace(/[^a-z0-9ğüşöçı]+/g, '-') + '-katalog.html', tpl.replace('/*__CATALOG_DATA__*/null', data), 'text/html');
  };
  CS.createCatalogOrder = function (o) {
    let c = CS.db.contacts.find((x) => o.phone && x.phone && x.phone.replace(/\D/g, '').endsWith(o.phone.replace(/\D/g, '').slice(-10)));
    if (!c && o.name) { c = { id: 'c_' + CS.uid(), name: o.name, phone: o.phone, kind: 'musteri', category: 'Toptan', address: o.address || '', createdAt: CS.today(), priceList: CS.db.settings.b2b?.list || 0 }; CS.db.contacts.push(c); }
    const lines = o.items.map((i) => { const p = CS.product(i.id); return { pid: p?.id || '', name: p ? CS.productName(p) : i.name, qty: CS.num(i.qty), unit: p?.unit || 'Adet', price: p ? CS.round(CS.num(i.price) / (1 + CS.num(p.kdv) / 100), 6) : CS.num(i.price), kdv: p ? CS.num(p.kdv) : 0, disc: 0 }; });
    const d = CS.postDoc({ type: 'siparis', date: CS.today(), cid: c?.id || '', buyer: o.name, channel: 'b2b', lines, currency: '₺', rate: 1, status: 'yeni', desc: o.note || '', shipAddress: o.address || '' });
    CS.toast('B2B sipariş oluşturuldu: ' + d.no); CS.refreshBadges && CS.refreshBadges(); CS.go('orders/view/' + d.id);
  };

  /* ================= BELGE DÜZENLEYİCİ ================= */
  function editor(page, d0, mod = 'docs') {
    if (!d0) { page.innerHTML = '<div class="blank"><h2>Belge bulunamadı</h2></div>'; return; }
    const isNew = !d0.id; const draft = CS.docDraft; CS.docDraft = null;
    const d = JSON.parse(JSON.stringify(Object.assign({ date: CS.today(), lines: [], currency: '₺', rate: 1, wh: CS.defaultWh(), status: '', gdisc: 0, gdiscPct: 0 }, d0, isNew && draft && draft.type === d0.type ? draft : {})));
    const TT = T[d.type]; const buy = TT.side === 'buy'; const isOrder = ['teklif', 'siparis', 'alis_siparis'].includes(d.type);
    if (!d.status) d.status = d.type === 'teklif' ? 'bekliyor' : isOrder ? 'yeni' : 'onay';
    if (isNew && !d.edoc) d.edoc = ['irsaliye', 'alis_irsaliye'].includes(d.type) ? 'kagit' : TT.invoice ? 'earsiv' : '';
    const contactKind = buy ? 'tedarikci' : 'musteri';
    if (d.plist == null) d.plist = CS.num(CS.contact(d.cid)?.priceList);
    const priceList = () => CS.num(d.plist);
    if (buy && !CS.canCost()) { page.innerHTML = '<div class="blank"><h2>Alış belgeleri için maliyet görme yetkisi gerekir</h2></div>'; return; }
    const body = CS.head(page, (isNew ? 'Yeni ' : '') + TT.label + (d.no ? ' ' + d.no : ''), `<a class="btn" href="#${mod}">Vazgeç</a>${CS.btn('Kaydet', 'save', 'primary', 'check')}${!isOrder && TT.cari ? CS.btn('Kaydet ve tahsil et', 'savepay', 'tag', 'wallet') : ''}`);
    body.classList.add('doc-edit');
    body.innerHTML = `<section class="panel"><div class="doc-head">
      <label class="fld" style="grid-column:span 2"><span>${buy ? 'Tedarikçi' : 'Müşteri'}</span><span class="row"><select id="dc" style="flex:1">${CS.contactOptions(null, isOrder || d.type === 'irsaliye' ? '— Cari seçin —' : '— Cari seçin —').map(([v, l]) => `<option value="${v}" ${v === d.cid ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select><button class="btn sm" id="dcn" type="button" title="Yeni cari">${icon('plus', 15)}</button></span><small id="dcb"></small></label>
      <label class="fld"><span>Belge tarihi</span><input type="date" id="dd" value="${d.date}"></label>
      <label class="fld"><span>${d.type === 'teklif' ? 'Geçerlilik tarihi' : isOrder ? 'Teslim / termin tarihi' : 'Vade tarihi'}</span><input type="date" id="ddue" value="${d.type === 'teklif' ? d.valid || CS.addDays(d.date, 15) : isOrder ? d.deliver || '' : d.due || ''}"></label>
      <label class="fld"><span>Belge no</span><input id="dno" value="${esc(d.no || '')}" placeholder="Otomatik"></label>
      ${TT.invoice || ['irsaliye', 'alis_irsaliye'].includes(d.type) ? `<label class="fld"><span>Belge tipi</span><select id="ded">${Object.entries(CS.EDOC).filter(([k]) => k !== 'fis').map(([k, v]) => `<option value="${k}" ${k === d.edoc ? 'selected' : ''}>${v}</option>`).join('')}</select></label>` : ''}
      ${TT.invoice ? `<label class="fld"><span>Senaryo</span><select id="dsc">${['TEMELFATURA', 'TICARIFATURA', 'EARSIVFATURA', 'IHRACAT', 'KAMU'].map((s) => `<option ${s === d.scenario ? 'selected' : ''}>${s}</option>`).join('')}</select></label>` : ''}
      ${TT.stock || isOrder ? `<label class="fld"><span>Depo</span><select id="dwh">${CS.whOptions().map(([v, l]) => `<option value="${v}" ${v === d.wh ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>` : ''}
      <label class="fld"><span>Para birimi / kur</span><span class="row"><select id="dcur" style="width:80px">${CS.CURRENCIES.map((c) => `<option ${c === d.currency ? 'selected' : ''}>${c}</option>`).join('')}</select><input id="drate" value="${CS.fmt2(d.rate)}" style="width:90px" inputmode="decimal" aria-label="Kur"></span></label>
      ${d.type === 'siparis' ? `<label class="fld"><span>Sipariş kanalı</span><select id="dch">${Object.entries(CS.CHANNELS).map(([k, v]) => `<option value="${k}" ${k === d.channel ? 'selected' : ''}>${v}</option>`).join('')}</select></label><label class="fld"><span>Pazaryeri sipariş no</span><input id="dmp" value="${esc(d.mpNo || '')}"></label>` : ''}
      ${isOrder ? `<label class="fld"><span>Durum</span><select id="dst">${Object.entries(d.type === 'teklif' ? CS.QUOTE_STATUS : CS.ORDER_STATUS).map(([k, v]) => `<option value="${k}" ${k === d.status ? 'selected' : ''}>${v}</option>`).join('')}</select></label>` : ''}
      ${['siparis', 'irsaliye'].includes(d.type) ? `<label class="fld"><span>Kargo firması</span><select id="dcargo"><option value="">—</option>${CS.CARGO.map((c) => `<option ${c === d.cargo ? 'selected' : ''}>${c}</option>`).join('')}</select></label><label class="fld"><span>Kargo takip no</span><input id="dcno" value="${esc(d.cargoNo || '')}"></label>` : ''}
      ${TT.invoice ? `<label class="fld"><span>İrsaliye no (varsa)</span><input id="dirs" value="${esc(d.irsNo || '')}"></label><label class="fld"><span>KDV tevkifatı</span><select id="dwt">${[['0', 'Yok'], ['2', '2/10'], ['3', '3/10'], ['4', '4/10'], ['5', '5/10'], ['7', '7/10'], ['9', '9/10'], ['10', 'Tam']].map(([v, l]) => `<option value="${v}" ${String(d.withholding || 0) === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label>` : ''}
      ${TT.invoice && d.type === 'alis' ? `<label class="fld"><span>Tedarikçi fatura no</span><input id="deno" value="${esc(d.eno || '')}"></label>` : ''}
      ${!buy ? `<label class="fld"><span>Fiyat listesi</span><select id="dpl">${CS.db.settings.priceLists.map((n, i) => `<option value="${i}" ${i === priceList() ? 'selected' : ''}>${esc(n)}</option>`).join('')}</select></label>` : ''}
      <label class="fld"><span>Proje</span><select id="dpr">${CS.projOptions().map(([v, l]) => `<option value="${v}" ${v === d.projectId ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>
      ${!buy ? `<label class="fld"><span>Satış temsilcisi</span><select id="dsel">${CS.db.users.map((u) => `<option value="${u.id}" ${u.id === (d.sellerId || CS.user.id) ? 'selected' : ''}>${esc(u.name)}</option>`).join('')}</select></label>` : ''}
      ${TT.stock ? `<label class="chk" style="padding-top:20px"><input type="checkbox" id="dns" ${d.noStock ? 'checked' : ''}> Stoğu etkilemesin${TT.invoice ? ' (irsaliyeli fatura)' : ''}</label>` : ''}
    </div></section>
    <section class="panel" style="margin-top:12px"><div class="row" style="margin-bottom:8px"><input id="dbc" placeholder="Barkod okutun ya da ürün adı yazıp Enter" style="flex:1;min-width:220px"><button class="btn" id="dadd" type="button">${icon('plus', 15)} Ürün ekle</button><button class="btn" id="dfree" type="button">Açıklama satırı</button>${buy ? `<button class="btn" id="dcrit" type="button">Kritik stokları ekle</button>` : ''}</div>
      <div style="overflow:auto"><table class="lines"><thead><tr><th>Ürün / hizmet</th><th>Miktar</th><th>Birim</th><th>Birim fiyat (KDV hariç)</th><th>İsk. %</th><th>KDV %</th><th>ÖTV %</th><th class="r">Tutar</th><th></th></tr></thead><tbody id="dl"></tbody></table></div>
      <div class="doc-sum"><table id="dsum"></table></div>
      <div class="form-grid" style="margin-top:10px"><label class="fld third"><span>Genel iskonto %</span><input id="dgp" value="${CS.fmt2(d.gdiscPct || 0)}" inputmode="decimal"></label><label class="fld third"><span>veya genel iskonto tutarı</span><input id="dga" value="${CS.fmt2(d.gdisc || 0)}" inputmode="decimal"></label><label class="fld third"><span>Belge kapsamı</span><input id="dsub" value="${esc(d.subject || '')}" placeholder="ör. Ekim ayı mal alımı"></label><label class="fld full"><span>Açıklama / not (belgede görünür)</span><textarea id="ddesc" rows="2">${esc(d.desc || '')}</textarea></label>${['siparis', 'irsaliye', 'satis'].includes(d.type) ? `<label class="fld full"><span>Teslimat adresi</span><input id="dship" value="${esc(d.shipAddress || '')}"></label>` : ''}</div></section>`;

    const drawLines = () => {
      $('#dl', body).innerHTML = d.lines.map((l, i) => { const c = CS.calcLine(l); const p = l.pid && CS.product(l.pid); return `<tr data-i="${i}"><td style="min-width:220px"><input data-k="name" value="${esc(l.name)}" aria-label="Ürün adı">${p && !p.service && (TT.stock || isOrder) ? `<small class="muted">Stok: ${CS.qty(CS.stockOf(p, d.wh))}</small>` : ''}</td><td class="w-q"><input data-k="qty" value="${CS.qty(l.qty)}" inputmode="decimal" aria-label="Miktar"></td><td class="w-s"><select data-k="unit" aria-label="Birim">${CS.db.units.map((u) => `<option ${u === l.unit ? 'selected' : ''}>${esc(u)}</option>`).join('')}</select></td><td class="w-p"><input data-k="price" value="${CS.fmt2(l.price)}" inputmode="decimal" aria-label="Birim fiyat"></td><td class="w-s"><input data-k="disc" value="${CS.fmt2(l.disc || 0)}" inputmode="decimal" aria-label="İskonto"></td><td class="w-s"><select data-k="kdv" aria-label="KDV">${CS.KDV_RATES.map((k) => `<option ${+k === +l.kdv ? 'selected' : ''}>${k}</option>`).join('')}</select></td><td class="w-s"><input data-k="otv" value="${CS.fmt2(l.otv || 0)}" inputmode="decimal" aria-label="ÖTV"></td><td class="w-t">${CS.fmt2(c.total)}</td><td><button type="button" class="icon-btn danger" data-del="${i}" aria-label="Satırı sil">${icon('trash', 15)}</button></td></tr>`; }).join('') || `<tr><td colspan="9" class="empty">Barkod okutun ya da “Ürün ekle” ile satır ekleyin.</td></tr>`;
      drawSum();
    };
    const drawSum = () => { const t = CS.calcDoc(d); const cur = d.currency; $('#dsum', body).innerHTML = `<tr><td>Brüt tutar</td><td class="r">${money(t.gross, cur)}</td></tr><tr><td>İskonto</td><td class="r">${money(t.disc, cur)}</td></tr><tr><td>KDV matrahı</td><td class="r">${money(t.net + t.otv, cur)}</td></tr>${t.otv ? `<tr><td>ÖTV</td><td class="r">${money(t.otv, cur)}</td></tr>` : ''}${Object.entries(t.kdvBy).filter(([, v]) => v).map(([k, v]) => `<tr><td>KDV %${k}</td><td class="r">${money(v, cur)}</td></tr>`).join('')}${t.withholding ? `<tr><td>Tevkif edilen KDV</td><td class="r">-${money(t.withholding, cur)}</td></tr>` : ''}<tr class="t"><td>Genel toplam</td><td class="r">${money(t.total, cur)}</td></tr>${cur !== '₺' ? `<tr><td>TL karşılığı</td><td class="r">${money(t.totalTry)}</td></tr>` : ''}`; };
    const addP = (p, qty = 1) => { if (!p) return; if (p.variants?.length) return CS.toast('Bu ürünün varyantını seçin.', 'bad'); if (d.currency !== '₺' && !CS.num(d.rate)) return CS.toast('Önce ' + d.currency + ' kurunu girin.', 'bad'); const fxSame = p.cur && p.cur !== '₺' && p.cur === d.currency; const price = buy ? (fxSame ? CS.num(p.buyFx) * (CS.num(d.rate) || 1) : CS.num(p.buy)) : CS.netPrice(p, priceList()); const ex = d.lines.find((l) => l.pid === p.id); if (ex) ex.qty = CS.num(ex.qty) + qty; else d.lines.push({ pid: p.id, name: CS.productName(p), qty, unit: p.unit || 'Adet', price: CS.round(buy && fxSame ? CS.num(p.buyFx) : !buy && fxSame && CS.rate(p.cur) ? price / CS.rate(p.cur) : price / (CS.num(d.rate) || 1), 4), kdv: CS.num(p.kdv), otv: CS.num(p.otv), disc: !buy ? CS.num(CS.contact(d.cid)?.discount) : 0 }); drawLines(); };
    const updCari = () => { const c = CS.contact(d.cid); $('#dcb', body).innerHTML = c ? `Bakiye: ${CS.balanceText(CS.balance(c.id))}${c.limit ? ' · limit ' + money(c.limit) : ''}${c.efatura ? ' · e-Fatura mükellefi' : ''}` : ''; };
    drawLines(); updCari();
    body.addEventListener('input', (e) => { const tr = e.target.closest('tr[data-i]'); if (tr && e.target.dataset.k) { const l = d.lines[+tr.dataset.i]; const k = e.target.dataset.k; l[k] = ['name', 'unit'].includes(k) ? e.target.value : CS.num(e.target.value); tr.querySelector('.w-t').textContent = CS.fmt2(CS.calcLine(l).total); drawSum(); } if (e.target.id === 'dgp') { d.gdiscPct = CS.num(e.target.value); d.gdisc = 0; $('#dga', body).value = '0,00'; drawSum(); } if (e.target.id === 'dga') { d.gdisc = CS.num(e.target.value); d.gdiscPct = 0; $('#dgp', body).value = '0,00'; drawSum(); } });
    body.addEventListener('change', (e) => {
      const id = e.target.id; if (e.target.dataset.k === 'kdv' || e.target.dataset.k === 'unit') { const tr = e.target.closest('tr'); d.lines[+tr.dataset.i][e.target.dataset.k] = e.target.dataset.k === 'kdv' ? +e.target.value : e.target.value; drawLines(); }
      if (id === 'dpl') { d.plist = +e.target.value; if (d.lines.length) { d.lines.forEach((l) => { const p = CS.product(l.pid); if (p) l.price = CS.round(CS.netPrice(p, d.plist) / (CS.num(d.rate) || 1), 4); }); drawLines(); } }
      if (id === 'dc') { d.cid = e.target.value; const c = CS.contact(d.cid); if (c) { d.plist = CS.num(c.priceList); const pls = $('#dpl', body); if (pls) pls.value = d.plist; if (c.due && !isOrder) { d.due = CS.addDays($('#dd', body).value, CS.num(c.due)); $('#ddue', body).value = d.due; } const ed = $('#ded', body); if (ed && TT.invoice) ed.value = c.efatura ? 'efatura' : 'earsiv'; const sc = $('#dsc', body); if (sc) sc.value = c.efatura ? 'TICARIFATURA' : 'EARSIVFATURA'; if (!buy && d.lines.length && confirm('Satır fiyatları müşterinin fiyat listesine göre güncellensin mi?')) { d.lines.forEach((l) => { const p = CS.product(l.pid); if (p) { l.price = CS.netPrice(p, priceList()); l.disc = CS.num(c.discount); } }); drawLines(); } } updCari(); }
      if (id === 'dwh') { d.wh = e.target.value; drawLines(); } if (id === 'dcur') { const oldRate = CS.num(d.rate) || 1; d.currency = e.target.value; const nr = d.currency === '₺' ? 1 : CS.rate(d.currency); d.rate = nr || 0; $('#drate', body).value = nr ? CS.fmt2(nr) : ''; if (!nr) { d._tl = oldRate; CS.toast(d.currency + ' kuru alınamadı. Kur alanına bugünkü kuru yazın; satır fiyatları ona göre çevrilir.', 'warn', 6000); $('#drate', body).focus(); } else if (d.lines.length) { d.lines.forEach((l) => { l.price = CS.round(CS.num(l.price) * oldRate / nr, 4); }); drawLines(); } drawSum(); } if (id === 'drate') { const nr = CS.num(e.target.value); d.rate = nr || (d.currency === '₺' ? 1 : 0); if (d._tl && nr && d.currency !== '₺') { const k = d._tl; delete d._tl; if (d.lines.length) { d.lines.forEach((l) => { l.price = CS.round(CS.num(l.price) * k / nr, 4); }); drawLines(); } } drawSum(); } if (id === 'dwt') { d.withholding = +e.target.value; drawSum(); }
    });
    body.addEventListener('click', (e) => { const del = e.target.closest('[data-del]'); if (del) { d.lines.splice(+del.dataset.del, 1); drawLines(); } const t = e.target.closest('button'); if (!t) return; if (t.id === 'dadd') CS.pickProduct((p) => addP(p), { multi: true, buy, wh: d.wh }); if (t.id === 'dfree') { d.lines.push({ pid: '', name: '', qty: 1, unit: 'Adet', price: 0, kdv: CS.db.settings.defaultKdv, disc: 0 }); drawLines(); } if (t.id === 'dcn') CS.contactForm({ kind: contactKind }, (c) => { const s = $('#dc', body); s.insertAdjacentHTML('beforeend', `<option value="${c.id}">${esc(c.name)}</option>`); s.value = c.id; d.cid = c.id; updCari(); }); if (t.id === 'dcrit') { CS.db.products.filter(CS.isCritical).filter((p) => !d.cid || !p.supplierId || p.supplierId === d.cid).forEach((p) => addP(p, Math.max(1, CS.num(p.critical) * 2 - CS.stockOf(p)))); } });
    $('#dbc', body).addEventListener('keydown', (e) => { if (e.key !== 'Enter') return; e.preventDefault(); const v = e.target.value.trim(); if (!v) return; const p = CS.findByBarcode(v); if (p) addP(p); else { CS.pickProduct((pp) => addP(pp), { multi: true, buy }); setTimeout(() => { const q = $('#pq'); if (q) { q.value = v; q.dispatchEvent(new Event('input')); } }, 40); } e.target.value = ''; });

    const collect = () => {
      d.cid = $('#dc', body).value; d.date = $('#dd', body).value; const due = $('#ddue', body).value; if (d.type === 'teklif') d.valid = due; else if (isOrder) d.deliver = due; else d.due = due;
      const g = (id) => $('#' + id, body); if (g('dno').value.trim()) d.no = g('dno').value.trim(); else if (isNew) delete d.no;
      if (g('ded')) d.edoc = g('ded').value; if (g('dsc')) d.scenario = g('dsc').value; if (g('dwh')) d.wh = g('dwh').value; d.currency = g('dcur').value; d.rate = d.currency === '₺' ? 1 : CS.num(g('drate').value);
      if (g('dch')) d.channel = g('dch').value; if (g('dmp')) d.mpNo = g('dmp').value; if (g('dst')) d.status = g('dst').value; if (g('dcargo')) d.cargo = g('dcargo').value; if (g('dcno')) d.cargoNo = g('dcno').value; if (g('dirs')) d.irsNo = g('dirs').value; if (g('deno')) d.eno = g('deno').value; if (g('dns')) d.noStock = g('dns').checked; if (g('dship')) d.shipAddress = g('dship').value;
      d.projectId = g('dpr').value; if (g('dsel')) d.sellerId = g('dsel').value; d.desc = g('ddesc').value; d.subject = g('dsub').value;
      d.lines = d.lines.filter((l) => l.name || l.pid);
      if (!d.lines.length) { CS.toast('En az bir satır ekleyin.', 'bad'); return false; } if (d.currency !== '₺' && !(d.rate > 0)) { CS.toast(d.currency + ' kuru girilmedi. Kur alanına bugünkü kuru yazın.', 'bad'); $('#drate', body).classList.add('err'); return false; } delete d._tl;
      if ((TT.cari || d.type === 'irsaliye' || isOrder) && !d.cid && !(d.type === 'siparis' && d.buyer)) { CS.toast('Cari seçin.', 'bad'); $('#dc', body).classList.add('err'); return false; }
      if (TT.stock < 0 && !CS.db.settings.negativeStock && !d.noStock) { const bad = d.lines.find((l) => l.pid && !CS.product(l.pid)?.service && CS.stockOf(l.pid, d.wh) + (isNew ? 0 : CS.sum(CS.db.moves.filter((m) => m.ref === d.id && m.pid === l.pid), (m) => -m.qty)) < CS.num(l.qty)); if (bad) { CS.toast(bad.name + ' için yeterli stok yok.', 'bad'); return false; } }
      const c = CS.contact(d.cid); if (c && CS.num(c.limit) && T[d.type].cari > 0 && CS.balance(c.id) + CS.calcDoc(d).totalTry > CS.num(c.limit) && !confirm(`${c.name} risk limitini aşıyor (${money(c.limit)}). Yine de kaydedilsin mi?`)) return false;
      if (TT.invoice && !d.uuid && ['efatura', 'earsiv', 'eihracat', 'esmm'].includes(d.edoc)) { d.uuid = crypto.randomUUID ? crypto.randomUUID().toUpperCase() : CS.uid(); d.estatus = 'taslak'; }
      return true;
    };
    const save = (pay) => { if (!collect()) return; const saved = CS.postDoc(d); if (d.fromId) { const src = CS.byId('docs', d.fromId); if (src) { src.status = d.type === 'siparis' ? 'siparis' : 'faturalandi'; src.convertedTo = saved.id; CS.save(); } } CS.toast(`${TT.label} kaydedildi: ${saved.no}`); CS.refreshBadges(); CS.go(mod + '/view/' + saved.id); if (CS.costChanges?.length && CS.canCost()) setTimeout(() => CS.costChangeDialog(CS.costChanges.slice()), 150); if (pay) setTimeout(() => CS.quickPayment(T[saved.type].cari > 0 ? 'in' : 'out', saved.cid, CS.round(saved.totalTry - CS.docPaid(saved)), saved.id), 100); };
    CS.bind(page, { save: () => save(false), savepay: () => save(true) });
    if (isNew) setTimeout(() => (d.cid ? $('#dbc', body) : $('#dc', body)).focus(), 50);
  }

  /* ================= BELGE GÖRÜNÜMÜ ================= */
  function view(page, d, mod = 'docs') {
    if (!d) { page.innerHTML = '<div class="blank"><h2>Belge bulunamadı</h2></div>'; return; }
    const TT = T[d.type]; const t = CS.calcDoc(d); const c = CS.contact(d.cid); const paid = CS.docPaid(d); const rest = CS.round(d.totalTry - paid); const ps = payState(d);
    const isOrder = ['teklif', 'siparis', 'alis_siparis'].includes(d.type);
    const conv = [];
    if (d.type === 'teklif') conv.push(['siparis', 'Siparişe dönüştür'], ['satis', 'Faturaya dönüştür']);
    if (d.type === 'siparis') conv.push(['satis', 'Faturaya dönüştür'], ['irsaliye', 'İrsaliye kes']);
    if (d.type === 'alis_siparis') conv.push(['alis', 'Alış faturasına dönüştür'], ['alis_irsaliye', 'Mal kabul (irsaliye)']);
    if (d.type === 'irsaliye') conv.push(['satis', 'Faturalandır']);
    if (d.type === 'alis_irsaliye') conv.push(['alis', 'Faturalandır']);
    if (d.type === 'satis' || d.type === 'pos') conv.push(['satis_iade', 'İade al']);
    if (d.type === 'alis') conv.push(['alis_iade', 'İade et']);
    if (d.type === 'pos') conv.push(['satis', 'Faturaya dönüştür']);
    const canE = CS.can(mod, 'e'), canD = CS.can(mod, 'd');
    const body = CS.head(page, `${TT.label} ${d.no}`, `<a class="btn" href="#${mod}${{ alis: '/buys', alis_iade: '/returns', satis_iade: '/returns', pos_iade: '/returns', irsaliye: '/desp', alis_irsaliye: '/desp', pos: '/receipts', siparis: '/sales', alis_siparis: '/buys' }[d.type] || ''}">Listeye dön</a>${CS.btn('Yazdır / PDF', 'print', '', 'print')}${TT.invoice ? CS.btn('UBL-TR XML', 'xml', '', 'down') : ''}${CS.btn('Gönder', 'send', '', 'send')}${['siparis', 'irsaliye', 'satis'].includes(d.type) ? CS.btn('Kargo etiketi', 'cargo', '', 'truck') : ''}${canE && d.status !== 'iptal' ? CS.btn('Düzenle', 'edit', '', 'edit') : ''}${TT.cari && d.status !== 'iptal' && rest > 0.009 && (d.cid || ['pos'].includes(d.type)) ? CS.btn(TT.cari > 0 ? 'Tahsilat al' : 'Ödeme yap', 'pay', 'primary', 'wallet') : ''}`);
    body.innerHTML = `${d.status === 'iptal' ? '<p class="alert">Bu belge iptal edilmiştir; stok ve cari etkisi yoktur.</p>' : ''}
      <div class="kpis">${CS.kpi('Genel toplam', money(t.total, d.currency), d.currency !== '₺' ? money(t.totalTry) + ' (kur ' + CS.fmt2(d.rate) + ')' : 'KDV ' + money(t.kdv), 'hl')}${TT.cari ? CS.kpi(TT.cari > 0 ? 'Tahsil edilen' : 'Ödenen', money(paid), ps ? `<span class="pill ${ps[0]}">${ps[1]}</span>` : '') + CS.kpi('Kalan', `<span class="${rest > 0.009 ? 'neg' : ''}">${money(Math.max(0, rest))}</span>`, d.due ? 'Vade ' + CS.date(d.due) : '') : ''}${CS.kpi('Cari', esc(c?.name || d.buyer || 'Perakende'), c ? CS.balanceText(CS.balance(c.id)) : '')}${d.edoc ? CS.kpi('Belge tipi', esc(CS.EDOC[d.edoc] || ''), d.uuid ? 'ETTN ' + esc(d.uuid.slice(0, 13)) + '…' : '') : ''}</div>
      <div class="grid g2" style="grid-template-columns:2fr 1fr"><section class="panel"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Ürün / hizmet</th><th class="r">Miktar</th><th class="r">Birim fiyat</th><th class="r">İsk.</th><th class="r">KDV</th><th class="r">Tutar</th></tr></thead><tbody>${d.lines.map((l) => { const lc = CS.calcLine(l); return `<tr><td>${l.pid ? `<a href="#products/${l.pid}">${esc(l.name)}</a>` : esc(l.name)}</td><td class="r">${CS.qty(l.qty)} ${esc(l.unit || '')}</td><td class="r">${CS.fmt2(l.price)}</td><td class="r">${l.disc ? '%' + CS.fmt2(l.disc) : ''}</td><td class="r">%${l.kdv}</td><td class="r">${CS.fmt2(lc.total)}</td></tr>`; }).join('')}</tbody></table></div>
        <div class="doc-sum"><table><tr><td>Ara toplam (KDV hariç)</td><td class="r">${money(t.net, d.currency)}</td></tr><tr><td>İskonto</td><td class="r">${money(t.disc, d.currency)}</td></tr>${Object.entries(t.kdvBy).filter(([, v]) => v).map(([k, v]) => `<tr><td>KDV %${k}</td><td class="r">${money(v, d.currency)}</td></tr>`).join('')}${t.withholding ? `<tr><td>Tevkifat</td><td class="r">-${money(t.withholding, d.currency)}</td></tr>` : ''}<tr class="t"><td>Toplam</td><td class="r">${money(t.total, d.currency)}</td></tr></table></div>${d.desc ? `<p class="muted">${esc(d.desc)}</p>` : ''}</section>
      <section class="panel"><h2>Belge bilgileri</h2><div class="list">${[['Tarih', CS.date(d.date)], ['Vade', CS.date(d.due)], ['Geçerlilik', CS.date(d.valid)], ['Termin', CS.date(d.deliver)], ['Depo', CS.whName(d.wh)], ['Kanal', CS.CHANNELS[d.channel]], ['Pazaryeri no', d.mpNo], ['Kargo', [d.cargo, d.cargoNo].filter(Boolean).join(' · ')], ['Durum', (d.type === 'teklif' ? CS.QUOTE_STATUS : isOrder ? CS.ORDER_STATUS : {})[d.status]], ['e-Belge durumu', d.uuid ? CS.EDOC_STATUS[d.estatus || 'taslak'] : ''], ['Senaryo', d.scenario], ['Tedarikçi fatura no', d.eno], ['İrsaliye no', d.irsNo], ['Proje', CS.byId('projects', d.projectId)?.name], ['Satış temsilcisi', CS.userName(d.sellerId)], ['Oluşturan', CS.userName(d.userId)], ['Oluşturma', CS.dateTime(d.createdAt)], ['Dönüştürüldü', d.convertedTo ? CS.byId('docs', d.convertedTo)?.no : '']].filter((x) => x[1]).map(([k, v]) => `<div><span class="muted">${k}</span><b>${esc(v)}</b></div>`).join('')}</div>
        ${conv.length && canE && d.status !== 'iptal' ? `<h2 style="margin-top:14px">Dönüştür</h2><div class="row">${conv.map(([k, l]) => `<button class="btn sm" data-conv="${k}">${l}</button>`).join('')}</div>` : ''}
        ${isOrder && canE ? `<h2 style="margin-top:14px">Durum</h2><div class="row">${Object.entries(d.type === 'teklif' ? CS.QUOTE_STATUS : CS.ORDER_STATUS).map(([k, v]) => `<button class="btn sm ${d.status === k ? 'primary' : ''}" data-st="${k}">${v}</button>`).join('')}</div>` : ''}
        ${d.uuid && canE ? `<h2 style="margin-top:14px">e-Belge</h2><div class="row">${Object.entries(CS.EDOC_STATUS).map(([k, v]) => `<button class="btn sm ${(d.estatus || 'taslak') === k ? 'primary' : ''}" data-es="${k}">${v}</button>`).join('')}</div>` : ''}
        <h2 style="margin-top:14px">Ödemeler</h2><div class="list">${CS.db.accMoves.filter((m) => m.docId === d.id).map((m) => `<div><span>${CS.date(m.date)} · ${esc(CS.account(m.accId)?.name || '')}</span><b>${money(Math.abs(m.amt))}</b></div>`).join('')}${CS.db.cheques.filter((x) => x.docId === d.id).map((x) => `<div><span>${x.kind === 'cek' ? 'Çek' : 'Senet'} ${esc(x.no)} · vade ${CS.date(x.due)}</span><b>${money(x.amount)}</b></div>`).join('') || (paid ? '' : '<p class="muted">Ödeme yok.</p>')}</div>
        <div class="row" style="margin-top:14px">${canE && d.status !== 'iptal' ? CS.btn('Kopyala', 'copy', 'sm', 'copy') + CS.btn('İptal et', 'cancel', 'sm', 'x') : ''}${canD ? CS.btn('Sil', 'del', 'sm danger', 'trash') : ''}</div></section></div>`;
    body.addEventListener('click', (e) => {
      const cv = e.target.closest('[data-conv]'); if (cv) { const nt = cv.dataset.conv; const nd = { type: nt, cid: d.cid, buyer: d.buyer, wh: d.wh, currency: d.currency, rate: d.rate, projectId: d.projectId, fromId: d.id, desc: `${d.no} numaralı ${T[d.type].label.toLowerCase()} kaynaklı`, lines: d.lines.map((l) => ({ ...l, cost: undefined })), gdisc: d.gdisc, gdiscPct: d.gdiscPct, shipAddress: d.shipAddress, channel: d.channel, mpNo: d.mpNo, irsNo: ['irsaliye', 'alis_irsaliye'].includes(d.type) ? d.no : '', noStock: ['irsaliye', 'alis_irsaliye'].includes(d.type) || (d.type === 'pos' && nt === 'satis'), edoc: '' }; if (d.type === 'pos' && nt === 'satis') { nd.fromPos = true; nd.noCari = true; nd.desc += ' (fiş ödemesi ve stoğu önceden işlendi)'; } CS.docDraft = nd; const m2 = ['teklif', 'siparis', 'alis_siparis'].includes(nt) ? 'orders' : 'docs'; CS.go(m2 + '/new/' + nt); setTimeout(() => {}, 0); return; }
      const s = e.target.closest('[data-st]'); if (s) { d.status = s.dataset.st; CS.log('Belge durumu', d.no + ' → ' + s.textContent); CS.save(); CS.route(); return; }
      const es = e.target.closest('[data-es]'); if (es) { d.estatus = es.dataset.es; CS.save(); CS.route(); }
    });
    CS.bind(page, {
      print: () => printDoc(d), xml: () => downloadXML(d), cargo: () => cargoLabel(d), edit: () => CS.go(mod + '/edit/' + d.id),
      pay: () => CS.quickPayment(TT.cari > 0 ? 'in' : 'out', d.cid, rest, d.id),
      send: () => { const txt = `${CS.db.company.name}\n${TT.label}: ${d.no}\nTarih: ${CS.date(d.date)}\nTutar: ${money(t.total, d.currency)}${d.due ? '\nVade: ' + CS.date(d.due) : ''}${d.uuid ? '\nETTN: ' + d.uuid : ''}`; CS.modal({ title: 'Belgeyi gönder', size: 'sm', body: `<p class="muted">Belgeyi önce “Yazdır / PDF” ile PDF olarak kaydedip eke ekleyebilirsiniz.</p><textarea id="st" rows="7" style="width:100%">${esc(txt)}</textarea>`, buttons: [{ label: 'E-posta', onClick: (x, el) => window.open(`mailto:${c?.email || ''}?subject=${encodeURIComponent(TT.label + ' ' + d.no)}&body=${encodeURIComponent($('#st', el).value)}`) }, { label: 'WhatsApp', kind: 'primary', onClick: (x, el) => window.open(`https://wa.me/${CS.waNum(c?.phone || '')}?text=${encodeURIComponent($('#st', el).value)}`) }] }); },
      copy: () => { CS.docDraft = { ...JSON.parse(JSON.stringify(d)), id: undefined, no: undefined, uuid: undefined, estatus: undefined, date: CS.today(), status: '' }; CS.go(mod + '/new/' + d.type); },
      cancel: () => CS.confirm('Belge iptal edilsin mi? Stok ve cari etkisi geri alınır, belge kayıtlarda kalır.', () => { d.status = 'iptal'; if (d.uuid) d.estatus = 'iptal'; CS.postDoc(d); CS.route(); }, 'İptal et'),
      del: () => CS.confirm('Belge ve bağlı ödemeler kalıcı olarak silinsin mi?', () => { CS.deleteDoc(d); CS.go(mod); })
    });
  }

  /* ---------- Yazdırma (A4) ---------- */
  function printDoc(d) {
    const co = CS.db.company; const c = CS.contact(d.cid); const TT = T[d.type]; const t = CS.calcDoc(d); const cur = d.currency;
    const html = `<div class="hdr"><div>${co.logo ? `<img src="${esc(co.logo)}" style="max-height:60px"><br>` : ''}<b style="font-size:15px">${esc(co.title || co.name)}</b><br>${esc(co.address)} ${esc(co.city)}<br>${co.phone ? 'Tel: ' + esc(co.phone) : ''} ${co.email ? '· ' + esc(co.email) : ''}<br>${co.taxNo ? 'VD: ' + esc(co.taxOffice) + ' · VKN: ' + esc(co.taxNo) : ''}${co.mersis ? '<br>Mersis: ' + esc(co.mersis) : ''}</div><div style="text-align:right"><h1>${esc(TT.label.toUpperCase())}</h1>${d.edoc && d.edoc !== 'kagit' && d.edoc !== 'fis' ? `<b>${esc(CS.EDOC[d.edoc])}</b><br>` : ''}No: <b>${esc(d.no)}</b><br>Tarih: ${CS.date(d.date)}${d.due ? '<br>Vade: ' + CS.date(d.due) : ''}${d.valid ? '<br>Geçerlilik: ' + CS.date(d.valid) : ''}${d.irsNo ? '<br>İrsaliye: ' + esc(d.irsNo) : ''}${d.uuid ? '<br><small>ETTN: ' + esc(d.uuid) + '</small>' : ''}</div></div>
      <div class="box" style="margin-bottom:10px"><b>${TT.side === 'buy' ? 'Tedarikçi' : 'Sayın'}</b><br>${esc(c?.title || c?.name || d.buyer || 'Perakende müşteri')}<br>${esc(c?.address || d.shipAddress || '')} ${esc(c?.district || '')} ${esc(c?.city || '')}<br>${c?.taxNo ? 'VD: ' + esc(c.taxOffice || '') + ' · VKN: ' + esc(c.taxNo) : c?.tc ? 'TCKN: ' + esc(c.tc) : ''}${c?.phone ? ' · Tel: ' + esc(c.phone) : ''}</div>
      ${d.subject ? `<p><b>Konu:</b> ${esc(d.subject)}</p>` : ''}
      <table><tr><th>#</th><th>Mal / hizmet</th><th class="r">Miktar</th><th class="r">Birim fiyat</th><th class="r">İsk.</th><th class="r">KDV</th><th class="r">Tutar</th></tr>${d.lines.map((l, i) => { const lc = CS.calcLine(l); return `<tr><td>${i + 1}</td><td>${esc(l.name)}</td><td class="r">${CS.qty(l.qty)} ${esc(l.unit || '')}</td><td class="r">${CS.fmt2(l.price)}</td><td class="r">${l.disc ? '%' + CS.fmt2(l.disc) : ''}</td><td class="r">%${l.kdv}</td><td class="r">${CS.fmt2(lc.net)}</td></tr>`; }).join('')}</table>
      <div style="display:flex;justify-content:space-between;gap:20px"><div style="flex:1"><p><b>Yalnız:</b> ${esc(CS.yaziyla ? CS.yaziyla(t.total) : '')}</p>${d.desc ? `<p>${esc(d.desc)}</p>` : ''}${co.iban && TT.side === 'sale' ? `<p>IBAN: ${esc(co.iban)}</p>` : ''}${d.type === 'teklif' ? '<p>Fiyatlarımıza belirtilen KDV dahil değildir. Teklif geçerlilik tarihine kadar geçerlidir.</p>' : ''}</div><table style="width:280px"><tr><td>Mal hizmet toplamı</td><td class="r">${CS.fmt2(t.gross)} ${cur}</td></tr><tr><td>Toplam iskonto</td><td class="r">${CS.fmt2(t.disc)} ${cur}</td></tr><tr><td>KDV matrahı</td><td class="r">${CS.fmt2(t.net + t.otv)} ${cur}</td></tr>${t.otv ? `<tr><td>ÖTV</td><td class="r">${CS.fmt2(t.otv)}</td></tr>` : ''}${Object.entries(t.kdvBy).filter(([, v]) => v).map(([k, v]) => `<tr><td>KDV (%${k})</td><td class="r">${CS.fmt2(v)} ${cur}</td></tr>`).join('')}${t.withholding ? `<tr><td>Tevkifat</td><td class="r">-${CS.fmt2(t.withholding)}</td></tr>` : ''}<tr class="tot"><td>Ödenecek tutar</td><td class="r">${CS.fmt2(t.total)} ${cur}</td></tr>${cur !== '₺' ? `<tr><td>TL karşılığı (kur ${CS.fmt2(d.rate)})</td><td class="r">${CS.fmt2(t.totalTry)} ₺</td></tr>` : ''}</table></div>
      ${['irsaliye', 'alis_irsaliye'].includes(d.type) ? '<br><table><tr><td>Teslim eden</td><td>Teslim alan</td></tr><tr><td><br><br></td><td></td></tr></table>' : ''}`;
    CS.printHTML(html, d.no);
  }
  CS.printDoc = printDoc;

  /* ---------- Kargo etiketi ---------- */
  function cargoLabel(d) { const co = CS.db.company; const c = CS.contact(d.cid); CS.printHTML(`<div class="lb"><div><small>GÖNDERİCİ</small><br><b>${esc(co.name)}</b><br>${esc(co.address)} ${esc(co.city)}<br>${esc(co.phone)}</div><div style="font-size:16px"><small>ALICI</small><br><b>${esc(c?.title || c?.name || d.buyer || '')}</b><br>${esc(d.shipAddress || c?.address || '')}<br>${esc(c?.district || '')} ${esc(c?.city || '')}<br>Tel: ${esc(c?.phone || '')}</div><div>${esc(d.cargo || 'Kargo')} · Sipariş ${esc(d.mpNo || d.no)}<br>${CS.barcodeSVG(d.cargoNo || d.no, 50)}</div><div><small>İÇERİK</small> ${d.lines.map((l) => CS.qty(l.qty) + ' ' + esc(l.name)).join(', ')}</div></div>`, 'Kargo etiketi', 'body{margin:0}.lb{width:100mm;padding:4mm;border:1px solid #000}.lb>div{border-bottom:1px dashed #000;padding:3mm 0}.lb svg{width:100%;height:50px}@page{size:100mm 150mm;margin:0}'); }

  /* ---------- UBL-TR XML ---------- */
  function downloadXML(d) {
    const co = CS.db.company; const c = CS.contact(d.cid) || {}; const t = CS.calcDoc(d); const cur = d.currency === '₺' ? 'TRY' : d.currency; const x = (s) => CS.esc(s ?? ''); const a = (n) => CS.round(n || 0).toFixed(2);
    if (!d.uuid) { d.uuid = crypto.randomUUID ? crypto.randomUUID().toUpperCase() : CS.uid(); CS.save(); }
    const party = (p, vkn, isUs) => `<cac:Party>${p.web ? `<cbc:WebsiteURI>${x(p.web)}</cbc:WebsiteURI>` : ''}<cac:PartyIdentification><cbc:ID schemeID="${String(vkn || '').length === 11 ? 'TCKN' : 'VKN'}">${x(vkn || '11111111111')}</cbc:ID></cac:PartyIdentification>${isUs && p.mersis ? `<cac:PartyIdentification><cbc:ID schemeID="MERSISNO">${x(p.mersis)}</cbc:ID></cac:PartyIdentification>` : ''}<cac:PartyName><cbc:Name>${x(p.title || p.name || 'Nihai tüketici')}</cbc:Name></cac:PartyName><cac:PostalAddress><cbc:StreetName>${x(p.address)}</cbc:StreetName><cbc:CitySubdivisionName>${x(p.district || p.city)}</cbc:CitySubdivisionName><cbc:CityName>${x(p.city)}</cbc:CityName><cac:Country><cbc:Name>${x(p.country || 'Türkiye')}</cbc:Name></cac:Country></cac:PostalAddress><cac:PartyTaxScheme><cac:TaxScheme><cbc:Name>${x(p.taxOffice)}</cbc:Name></cac:TaxScheme></cac:PartyTaxScheme><cac:Contact><cbc:Telephone>${x(p.phone)}</cbc:Telephone><cbc:ElectronicMail>${x(p.email)}</cbc:ElectronicMail></cac:Contact>${String(vkn || '').length === 11 ? `<cac:Person><cbc:FirstName>${x((p.title || p.name || '').split(' ').slice(0, -1).join(' ') || p.name)}</cbc:FirstName><cbc:FamilyName>${x((p.title || p.name || '').split(' ').slice(-1)[0])}</cbc:FamilyName></cac:Person>` : ''}</cac:Party>`;
    const buy = T[d.type].side === 'buy';
    const sup = buy ? party(c, c.taxNo || c.tc, false) : party(co, co.taxNo, true); const cus = buy ? party(co, co.taxNo, true) : party(c, c.taxNo || c.tc, false);
    const ratio = (CS.sum(d.lines, (l) => CS.calcLine(l).total) || 1) ? t.total / (CS.sum(d.lines, (l) => CS.calcLine(l).total) || 1) : 1;
    const lines = d.lines.map((l, i) => { const lc = CS.calcLine(l); return `<cac:InvoiceLine><cbc:ID>${i + 1}</cbc:ID><cbc:InvoicedQuantity unitCode="${({ Adet: 'C62', Kg: 'KGM', Gr: 'GRM', Lt: 'LTR', Mt: 'MTR', Paket: 'PA', Koli: 'CS', Kutu: 'BX', Saat: 'HUR' })[l.unit] || 'C62'}">${CS.round(CS.num(l.qty), 3)}</cbc:InvoicedQuantity><cbc:LineExtensionAmount currencyID="${cur}">${a(lc.net)}</cbc:LineExtensionAmount>${lc.discAmt ? `<cac:AllowanceCharge><cbc:ChargeIndicator>false</cbc:ChargeIndicator><cbc:MultiplierFactorNumeric>${CS.num(l.disc) / 100}</cbc:MultiplierFactorNumeric><cbc:Amount currencyID="${cur}">${a(lc.discAmt)}</cbc:Amount><cbc:BaseAmount currencyID="${cur}">${a(lc.gross)}</cbc:BaseAmount></cac:AllowanceCharge>` : ''}<cac:TaxTotal><cbc:TaxAmount currencyID="${cur}">${a(lc.kdvAmt)}</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxableAmount currencyID="${cur}">${a(lc.net + lc.otvAmt)}</cbc:TaxableAmount><cbc:TaxAmount currencyID="${cur}">${a(lc.kdvAmt)}</cbc:TaxAmount><cbc:Percent>${l.kdv}</cbc:Percent><cac:TaxCategory><cac:TaxScheme><cbc:Name>KDV</cbc:Name><cbc:TaxTypeCode>0015</cbc:TaxTypeCode></cac:TaxScheme></cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal><cac:Item><cbc:Name>${x(l.name)}</cbc:Name>${l.pid ? `<cac:SellersItemIdentification><cbc:ID>${x(CS.product(l.pid)?.barcode || CS.product(l.pid)?.code || '')}</cbc:ID></cac:SellersItemIdentification>` : ''}</cac:Item><cac:Price><cbc:PriceAmount currencyID="${cur}">${CS.round(CS.num(l.price), 4)}</cbc:PriceAmount></cac:Price></cac:InvoiceLine>`; }).join('');
    const profile = d.scenario || (d.edoc === 'earsiv' ? 'EARSIVFATURA' : 'TICARIFATURA');
    const xml = `<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2" xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2" xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2" xmlns:ext="urn:oasis:names:specification:ubl:schema:xsd:CommonExtensionComponents-2">
<cbc:UBLVersionID>2.1</cbc:UBLVersionID><cbc:CustomizationID>TR1.2</cbc:CustomizationID><cbc:ProfileID>${profile}</cbc:ProfileID><cbc:ID>${x(d.eno && buy ? d.eno : d.no.replace(/^(\D+)/, (m) => m.padEnd(3, 'X').slice(0, 3)))}</cbc:ID><cbc:CopyIndicator>false</cbc:CopyIndicator><cbc:UUID>${d.uuid}</cbc:UUID><cbc:IssueDate>${d.date}</cbc:IssueDate><cbc:IssueTime>${(d.createdAt || CS.now()).slice(11, 19)}</cbc:IssueTime><cbc:InvoiceTypeCode>${T[d.type].ret ? 'IADE' : t.withholding ? 'TEVKIFAT' : 'SATIS'}</cbc:InvoiceTypeCode>${d.desc ? `<cbc:Note>${x(d.desc)}</cbc:Note>` : ''}<cbc:Note>Yalnız: ${x(CS.yaziyla ? CS.yaziyla(t.total) : '')}</cbc:Note><cbc:DocumentCurrencyCode>${cur}</cbc:DocumentCurrencyCode><cbc:LineCountNumeric>${d.lines.length}</cbc:LineCountNumeric>
${d.irsNo ? `<cac:DespatchDocumentReference><cbc:ID>${x(d.irsNo)}</cbc:ID><cbc:IssueDate>${d.date}</cbc:IssueDate></cac:DespatchDocumentReference>` : ''}
<cac:AccountingSupplierParty>${sup}</cac:AccountingSupplierParty><cac:AccountingCustomerParty>${cus}</cac:AccountingCustomerParty>
${d.due ? `<cac:PaymentTerms><cbc:PaymentDueDate>${d.due}</cbc:PaymentDueDate></cac:PaymentTerms>` : ''}
${cur !== 'TRY' ? `<cac:PricingExchangeRate><cbc:SourceCurrencyCode>${cur}</cbc:SourceCurrencyCode><cbc:TargetCurrencyCode>TRY</cbc:TargetCurrencyCode><cbc:CalculationRate>${d.rate}</cbc:CalculationRate></cac:PricingExchangeRate>` : ''}
<cac:TaxTotal><cbc:TaxAmount currencyID="${cur}">${a(t.kdv)}</cbc:TaxAmount>${Object.entries(t.kdvBy).map(([k, v]) => `<cac:TaxSubtotal><cbc:TaxableAmount currencyID="${cur}">${a(CS.sum(d.lines.filter((l) => +l.kdv === +k), (l) => CS.calcLine(l).net) * ratio)}</cbc:TaxableAmount><cbc:TaxAmount currencyID="${cur}">${a(v)}</cbc:TaxAmount><cbc:Percent>${k}</cbc:Percent><cac:TaxCategory>${+k === 0 ? '<cbc:TaxExemptionReasonCode>351</cbc:TaxExemptionReasonCode><cbc:TaxExemptionReason>KDV istisna olmayan diğer</cbc:TaxExemptionReason>' : ''}<cac:TaxScheme><cbc:Name>KDV</cbc:Name><cbc:TaxTypeCode>0015</cbc:TaxTypeCode></cac:TaxScheme></cac:TaxCategory></cac:TaxSubtotal>`).join('')}</cac:TaxTotal>
${t.withholding ? `<cac:WithholdingTaxTotal><cbc:TaxAmount currencyID="${cur}">${a(t.withholding)}</cbc:TaxAmount></cac:WithholdingTaxTotal>` : ''}
<cac:LegalMonetaryTotal><cbc:LineExtensionAmount currencyID="${cur}">${a(t.gross)}</cbc:LineExtensionAmount><cbc:TaxExclusiveAmount currencyID="${cur}">${a(t.net + t.otv)}</cbc:TaxExclusiveAmount><cbc:TaxInclusiveAmount currencyID="${cur}">${a(t.net + t.otv + t.kdv)}</cbc:TaxInclusiveAmount><cbc:AllowanceTotalAmount currencyID="${cur}">${a(t.disc)}</cbc:AllowanceTotalAmount><cbc:PayableAmount currencyID="${cur}">${a(t.total)}</cbc:PayableAmount></cac:LegalMonetaryTotal>
${lines}
</Invoice>`;
    if (!d.estatus || d.estatus === 'taslak') { d.estatus = 'hazir'; CS.save(); }
    CS.download(d.no + '.xml', xml, 'application/xml');
  }
  CS.downloadXML = downloadXML;

  /* ---------- Alış sonrası maliyet / kâr değişimi ---------- */
  CS.costChangeDialog = function (list) {
    const rows = list.map((c, i) => { const p = CS.product(c.pid); if (!p) return ''; const fx = c.cur !== '₺'; const r = fx ? CS.rate(c.cur) : 1; const kdvMul = CS.db.settings.priceIncludesKdv ? 1 + CS.num(p.kdv) / 100 : 1; const newBuyTL = c.nw * r; const keep = CS.round(newBuyTL * (1 + c.marginBefore / 100) * kdvMul, 2); const mNow = newBuyTL ? ((CS.num(p.sell) / kdvMul - newBuyTL) / newBuyTL) * 100 : 0;
      return `<tr><td>${esc(CS.productName(p))}</td><td class="r">${CS.fxMoney(c.old, c.cur)}</td><td class="r">${CS.fxMoney(c.unit, c.cur)}</td><td class="r"><b>${CS.fxMoney(c.nw, c.cur)}</b></td><td class="r">${CS.fmt2(p.sell)} <small>%${CS.fmt2(c.marginBefore)} → <span class="${mNow < c.marginBefore ? 'neg' : 'pos'}">%${CS.fmt2(mNow)}</span></small></td><td class="r">${c.auto ? '<span class="pill ok">otomatik güncellendi</span>' : `<label class="row" style="justify-content:flex-end"><input type="checkbox" data-keep="${i}" ${mNow < c.marginBefore ? 'checked' : ''}> ${CS.fmt2(keep)}</label>`}</td></tr>`; }).join('');
    CS.modal({ title: 'Alış fiyatı değişti: kâr yeniden hesaplandı', size: 'xl', body: `<p class="muted">Stoktaki ürünlere farklı fiyattan alış yapıldı. Yeni maliyet ${CS.db.settings.costMethod === 'son' ? 'son alış fiyatıdır' : 'eldeki stok ile yeni alışın ağırlıklı ortalamasıdır'}. Kâr marjını korumak istediğiniz ürünlerin satış fiyatını güncelleyebilirsiniz.</p><div class="tbl-wrap"><table class="tbl"><tr><th>Ürün</th><th class="r">Eski maliyet</th><th class="r">Bu alış</th><th class="r">Yeni maliyet</th><th class="r">Satış fiyatı ve kâr</th><th class="r">Eski kârı koruyan fiyat</th></tr>${rows}</table></div>`, buttons: [{ label: 'Fiyatlara dokunma' }, { label: 'Seçilenlerin fiyatını güncelle', kind: 'primary', onClick: (cl, el) => { let n = 0; el.querySelectorAll('[data-keep]:checked').forEach((cb) => { const c = list[+cb.dataset.keep]; const p = CS.product(c.pid); const r = c.cur !== '₺' ? CS.rate(c.cur) : 1; const kdvMul = CS.db.settings.priceIncludesKdv ? 1 + CS.num(p.kdv) / 100 : 1; const ns = CS.round(c.nw * r * (1 + c.marginBefore / 100) * kdvMul, 2); (p.priceHist = p.priceHist || []).push({ at: CS.now(), user: CS.user.name, sellOld: p.sell, sellNew: ns, note: 'Maliyet değişimi' }); const ratio = CS.num(p.sell) ? ns / CS.num(p.sell) : 1; if (c.cur !== '₺') p.sellFx = CS.round(ns / r, 4); p.sell = ns; p.prices = (p.prices || []).map((x, k) => (k === 0 ? ns : CS.num(x) ? CS.round(CS.num(x) * ratio, 2) : x)); (p.dealers || []).forEach((d) => { if (d && CS.num(d.p) && (d.m === '' || d.m == null)) d.p = CS.round(CS.num(d.p) * ratio, 4); }); n++; }); if (n) { CS.save(); CS.toast(n + ' ürünün fiyatı eski kâr oranına göre güncellendi.'); CS.route(); } } }] });
  };
})();
